cultyStatus":null,"review":null}}},{"gid":"e1018-t3-math_m2-56","subject":"SAT Math","format":"mc","skillType":"Algebra (선형식·연립·부등식)","difficulty":"medium","skill":"linear_inequalities","examSystem":"sat_math","createdVia":"compiler","subpattern":"point_in_solution","group":null,"passage":"Consider the inequality shown.\n\n$y < 4x - 1$","question":"Which of the following points is a solution to the inequality shown?","options":["(6, -4)","(1, 3)","(-3, 6)","(-2, 5)"],"correctIndex":0,"answers":null,"explanation":"경계선 y = 4x - 1 (경계선 제외)을 기준으로, y 값이 경계선의 값보다 작다 쪽이 해 영역이다. (6, -4)를 대입하면 조건을 만족하므로 정답이다.","explanationEn":"Relative to the boundary line y = 4x - 1 (boundary excluded), the solution region is where the y-value is less than the boundary's value. Substituting (6, -4) satisfies the condition, so it is the correct answer.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T00:03:00.318Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"medium","requestedDifficulty":"medium","difficultyReasons":[],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"2026-10-19T23:55:29.089Z","mockExamGeneration":{"runId":"sat-error-report-1018","gid":"e1018-t3-math_m2-56","intendedSkill":"linear_inequalities","recipeId":null,"recipeCheck":null,"hardBasis":null,"difficultyStatus":null,"review":null}}},{"gid":"e1018-t7-math_m2-56","subject":"SAT Math","format":"spr","skillType":"Advanced Math (이차·지수·다항)","difficulty":"medium","skill":"nonlinear_equations_systems","examSystem":"sat_math","createdVia":"compiler","subpattern":"irrational_product_of_roots","group":null,"passage":"Consider the equation shown.\n\n$x^2 + 4x - 76 = 0$","question":"What is the product of the solutions to the equation shown?","options":null,"correctIndex":null,"answers":["-76"],"explanation":"판별식 D = b² - 4ac = 320는 완전제곱수가 아니므로 두 근은 무리수다. 하지만 근의 곱은 항상 유리수인 c/a로 구할 수 있다: -76/1 = -76. 근을 직접 구해 곱할 필요가 없다.","explanationEn":"The discriminant D = b² - 4ac = 320 is not a perfect square, so the two roots are irrational. But the product of the roots is always the rational value c/a: -76/1 = -76. There is no need to compute the individual roots.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T00:03:00.318Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"medium","requestedDifficulty":"medium","difficultyReasons":[],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"2026-10-19T23:55:29.102Z","mockExamGeneration":{"runId":"sat-error-report-1018","gid":"e1018-t7-math_m2-56","intendedSkill":"nonlinear_equations_systems","recipeId":null,"recipeCheck":null,"hardBasis":null,"difficultyStatus":null,"review":null}}},{"gid":"e1018-t8-math_m2-55","subject":"SAT Math","format":"spr","skillType":"Advanced Math (이차·지수·다항)","difficulty":"medium","skill":"nonlinear_equations_systems","examSystem":"sat_math","createdVia":"compiler","subpattern":"linear_quadratic_intersection","group":null,"passage":"Consider the system of equations shown.\n\n$y = -2x^2 - 5x - 11$\n$y = 7x + 7$","question":"What is the x-coordinate of the intersection point of the graphs of the equations shown?","options":null,"correctIndex":null,"answers":["-3"],"explanation":"두 식을 같다고 놓으면 -2x² - 5x - 11 = 7x + 7이고, 정리하면 -2x² - 12x - 18 = 0이다. 이 식은 (x + 3)² = 0 형태로 인수분해되어 중근 x = -3을 갖는다(직선이 포물선에 한 점에서 접한다). 따라서 교점의 x좌표는 -3이다.","explanationEn":"Setting the two expressions equal gives -2x² - 5x - 11 = 7x + 7, which simplifies to -2x² - 12x - 18 = 0. This factors as (x + 3)² = 0, a repeated root x = -3 (the line is tangent to the parabola at one point). So the x-coordinate of the intersection point is -3.","figure":null,"statements":null,"evidenceTarget":null,"evidenceSpan":null,"answerRationale":null,"distractorErrorTypes":null,"renderCheck":{"ok":true,"renderer":"std-1","checkedAt":"2026-10-20T00:03:00.318Z","issues":[]},"publish":true,"quality":{"contract":{"ok":true,"issues":[]},"estimatedDifficulty":"medium","requestedDifficulty":"medium","difficultyReasons":[],"distractors":[],"independentReview":{"pickedIndex":null,"pickedAnswer":null,"agrees":true,"confidence":"high","flags":[]},"needsReview":false,"needsReviewReasons":[],"calibrated":false,"reviewedAt":"2026-10-19T23:55:29.110Z","mockExamGeneration":{"runId":"sat-error-report-1018","gid":"e1018-t8-math_m2-55","intendedSkill":"nonlinear_equations_systems","recipeId":null,"recipeCheck":null,"hardBasis":null,"difficultyStatus":null,"review":null}}}]$satx$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1);
  r jsonb; v_pid uuid; v_vid uuid; v_n int := 0; v_skip int := 0;
begin
  if v_actor is null then raise exception 'No admin profile found.'; end if;
  for r in select * from jsonb_array_elements(v_items) loop
    if exists (select 1 from problem_versions where quality->'mockExamGeneration'->>'gid' = r->>'gid') then v_skip := v_skip + 1; continue; end if;
    v_pid := public.create_bank_problem(p_subject_id => (select id from subjects where name = r->>'subject' and archived_at is null), p_format => r->>'format', p_skill_type => r->>'skillType', p_topic => '',
      p_difficulty => r->>'difficulty', p_actor_id => v_actor, p_skill_code => r->>'skill', p_exam_system => r->>'examSystem', p_ap_subject => null, p_usage_scope => 'mock_exam');
    update problems set created_via = r->>'createdVia', subpattern = coalesce(r->>'subpattern', subpattern), similarity_group = coalesce(r->>'group', similarity_group) where id = v_pid;
    v_vid := public.save_problem_draft_version(p_problem_id => v_pid, p_passage => r->>'passage', p_options => nullif(r->'options', 'null'::jsonb), p_correct_index => (r->>'correctIndex')::int, p_explanation => r->>'explanation',
      p_difficulty => r->>'difficulty', p_actor_id => v_actor, p_answers => nullif(r->'answers', 'null'::jsonb), p_figure => nullif(r->'figure', 'null'::jsonb), p_figure_checked => false, p_statements => nullif(r->'statements', 'null'::jsonb),
      p_question => r->>'question', p_repair_status => null, p_explanation_en => r->>'explanationEn', p_evidence_target => r->>'evidenceTarget', p_evidence_span => r->>'evidenceSpan', p_answer_rationale => r->>'answerRationale',
      p_distractor_error_types => nullif(r->'distractorErrorTypes', 'null'::jsonb));
    perform public.set_problem_render_check(v_vid, r->'renderCheck');
    perform public.set_problem_quality(v_vid, r->'quality');
    if (r->>'publish')::boolean then perform public.confirm_and_publish_problem_version(v_vid, v_actor); end if;
    v_n := v_n + 1;
  end loop;
  raise notice 'SAT Math replacement import 1/1: created=% skipped(existing)=%', v_n, v_skip;
end
$imp$;
